Translate("frFR", "the-stockade", {
	title = "La Prison",
	aliases = { "Prison", "Prison de Stormwind" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Prison est la geôle de {link:stormwind-city}Stormwind{/link}. Elle s'étend sous la cité, derrière une porte sinistre au bord des canaux, près du quartier des Mages. Ses cellules enferment les pires criminels du royaume : meurtriers, rebelles, pillards {link:dark-iron-dwarves}Sombrefer{/link} et, surtout, les hommes capturés de la {link:defias-brotherhood}Confrérie défias{/link}. Pendant des années, elle fut la réponse silencieuse à chaque désordre du royaume. Elle est aujourd'hui un désordre à elle seule. Les prisonniers se sont soulevés, ont chassé leurs gardes et se sont emparés des quartiers de cellules.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne dit quand la Prison fut bâtie, ni qui en garda les clés le premier. À mesure que les {link:defias-brotherhood}Défias{/link} s'enhardissaient dans la {link:westfall}Marche de l'Ouest{/link} et dans {link:elwynn-forest}Elwynn{/link}, ses cellules se remplirent d'hommes aux bandanas rouges.]=],
		},
		{
			title = "Le temps présent",
			text = [=[L'émeute commença parmi les prisonniers défias et gagna chaque quartier. Le gardien {link:warden-thelwater}Thelwater{/link} et ses gardes ne tiennent plus que l'entrée. À l'intérieur, les détenus règnent sur les couloirs, et les plus dangereux d'entre eux ont fait des cellules leurs forteresses. À leur tête se tient {link:bazil-thredd}Bazil Thredd{/link}, l'un des lieutenants d'{link:edwin-vancleef}Edwin VanCleef{/link}. Thredd ne s'est pas soulevé seul. Avant l'émeute, il reçut un visiteur venu de l'extérieur, et la piste de ce visiteur mène au donjon de {link:stormwind-city}Stormwind{/link}.]=],
		},
		{
			title = "Détenus",
			text = [=[• {b}{link:bazil-thredd}Bazil Thredd{/link}.{/b} Le lieutenant défias qui mène le soulèvement.
• {b}{link:targorr-the-dread}Targorr le Terrible{/link}.{/b} Un prisonnier dont {link:lakeshire}Lakeshire{/link} n'a pas pardonné les crimes.
• {b}{link:kam-deepfury}Kam Deepfury{/link}.{/b} Un prisonnier {link:dark-iron-dwarves}Sombrefer{/link} recherché par les nains de {link:dun-modr}Dun Modr{/link}.
• {b}{link:dextren-ward}Dextren Ward{/link}.{/b} Un criminel dont le conseil de {link:darkshire}Darkshire{/link} a réclamé la main.
• {b}{link:hamhock}Hamhock{/link}.{/b} Un {link:ogres}ogre{/link} d'une grande taille et d'une maigre patience, lâché parmi les cellules.
• {b}{link:bruegal-ironknuckle}Bruegal Ironknuckle{/link}.{/b} Un prisonnier rarement vu et très redouté, venu des quartiers les plus profonds.
• {b}Les détenus défias.{/b} Prisonniers, forçats, captifs et insurgés qui règnent désormais sur les couloirs.]=],
		},
		{
			title = "Traditions de la Prison",
			text = [=[• Les villes du royaume ont la mémoire longue. {link:lakeshire}Lakeshire{/link}, {link:darkshire}Darkshire{/link} et les nains des {link:wetlands}Paluns{/link} ont chacun ici un prisonnier qu'ils veulent voir répondre de ses crimes.
• Les bandanas rouges des {link:defias-brotherhood}Défias{/link} se portent jusque dans les cellules. Dans la {link:old-town}Vieille ville{/link}, Nikova Raskol en a demandé un très grand nombre.
• L'émeute de la Prison n'est pas l'affaire du seul gardien. C'est le premier fil d'un complot qui mène des {link:the-deadmines}Mortemines{/link} au donjon de {link:stormwind-city}Stormwind{/link}.]=],
		},
	},
})

Translate("frFR", "bazil-thredd", {
	title = "Bazil Thredd",
	subtitle = "Meneur de l'émeute de la Prison",
	found = "Le quartier de cellules le plus profond de la Prison",
	hint = [=[Affrontez le lieutenant défias qui mène l'émeute de la Prison.]=],
	allegiance = "Confrérie défias",
	aliases = { "Thredd" },
	sections = {
		{
			title = "Résumé",
			text = [=[Bazil Thredd est un lieutenant d'{link:edwin-vancleef}Edwin VanCleef{/link} et un capitaine de la {link:defias-brotherhood}Confrérie défias{/link}. La Couronne l'avait fait enfermer dans la {link:the-stockade}Prison{/link}. Les murs ne le retinrent pas longtemps. Il mène aujourd'hui l'émeute qui a fait de la geôle de {link:stormwind-city}Stormwind{/link} une place forte défias sous la capitale.]=],
		},
		{
			title = "Importance",
			text = [=[Thredd est plus qu'un émeutier. Son soulèvement fut préparé, et quelqu'un hors de la prison l'aida à le préparer. Par Thredd, la guerre de la Confrérie passe des champs de la {link:westfall}Marche de l'Ouest{/link} au cœur même de la {link:stormwind-city}Cité de Stormwind{/link}.

Sa révolte montre aussi que la Confrérie n'abandonne pas les siens. Les hommes que la Couronne avait pris se soulevèrent dans la prison même qui devait les briser, et la {link:the-stockade}Prison{/link} devint une seconde place forte défias sous la capitale.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il servit {link:edwin-vancleef}VanCleef{/link} comme l'un des lieutenants de la Confrérie.
• Il mena les prisonniers de la {link:the-stockade}Prison{/link} dans leur révolte contre leurs gardes.
• Il reçut un visiteur secret avant le début de l'émeute.]=],
		},
	},
	chapters = {
		{
			title = "L'émeute",
			hint = "Mettez fin au meneur de l'émeute de la Prison.",
			text = [=[Le gardien {link:warden-thelwater}Thelwater{/link} ne pouvait reprendre sa prison tant que Thredd vivait. Quand le lieutenant tomba dans les profondeurs de la {link:the-stockade}Prison{/link}, l'émeute perdit sa tête. Sa propre tête fut rapportée au gardien, à la porte.]=],
		},
		{
			title = "Le visiteur",
			hint = "Découvrez qui vint voir Bazil Thredd avant l'émeute.",
			text = [=[Le gardien se souvenait d'un étrange visiteur venu à la cellule de Thredd peu avant le soulèvement. Il consigna tout ce dont il se souvenait et le scella. Cette description scellée voyagea de la {link:the-stockade}Prison{/link} jusqu'à l'architecte de la cité, puis de lui jusqu'au maître du {link:si-7}SI:7{/link}. Elle mena, au bout du compte, à un traître au donjon de {link:stormwind-city}Stormwind{/link}.]=],
		},
	},
	mentions = {
		{ text = "La lettre jamais envoyée" },
		{ text = "Bazil Thredd" },
		{ text = "Les émeutes de la {link:the-stockade}Prison{/link}" },
		{ text = "Le curieux visiteur" },
	},
	bonds = {
		{ id = "edwin-vancleef", name = "Edwin VanCleef", note = "son maître" },
		{ id = "warden-thelwater", name = "Gardien Thelwater", note = "son geôlier" },
		{ id = "baros-alexston", name = "Baros Alexston", note = "lança la traque contre lui" },
		{ id = "gregor-lescovar", name = "Gregor Lescovar", note = "le traître auquel mena son visiteur" },
	},
})

